-- ============================================================
-- Migration 079: phone-upload sessions - organization-scoped storage path,
--                attach without the rolled-back UPDATE, completion bound to
--                the session's own object (Phase G follow-up,
--                docs/selfhost-migration/phase-g/upload-security-and-077.md §2)
--
-- PURPOSE / WHAT IT DOES
--   Three RPC bodies, each byte-identical to the deployed version except ONE
--   targeted hunk (generated by gen079.py, which asserts every diff is
--   exactly that hunk):
--   1. create_product_image_upload_session (070 body): the session's
--      storage_path becomes org/<caller org>/temp/<sessionId> (was
--      temp/<sessionId>), matching 078's path-based storage policies. The
--      path is minted server-side and returned to the desktop
--      (storagePath), which signs it with createSignedUploadUrl; the phone
--      reads it back through _by_token. No client change is needed for this
--      part - every client uses the server's storagePath.
--   2. attach_product_image_upload_session_token (production body, unchanged
--      since 019): same defect class as 075 - the inactive/expired branch ran
--      UPDATE ... SET status='EXPIRED', signed_upload_token=NULL and then
--      RAISEd, which rolled the UPDATE back. The dead UPDATE is removed; the
--      message is unchanged ('Upload link is no longer active', the common
--      inactive-session message). Expiry stays derived from expires_at and is
--      persisted by the non-raising readers (status poll, _by_token).
--   3. complete_product_image_upload_session (075 body): p_public_url must END
--      with '/storage/v1/object/public/product-images/' || storage_path.
--      Before, any URL containing that substring was accepted, so the holder
--      of a phone token could hand the desktop an arbitrary URL (another
--      host, another object) that the desktop then stores in
--      products.image_url. The phone page sends getPublicUrl(storagePath),
--      which always satisfies the rule.
--   Signatures, return shapes, SECURITY DEFINER, search_path and grants are
--   unchanged (anon keeps EXECUTE on complete_..., 064/075).
--
-- WHAT IT CANNOT DO (doc §2c): a storage signed upload token, once issued, is
--   a stateless JWT (storage-api v1.74 signUploadObjectUrl/verifyObjectSignature:
--   valid until its exp, no revocation list). The session gates ISSUING it
--   (078 INSERT policy at createSignedUploadUrl time, attach refuses inactive
--   sessions, _by_token hands it out only while PENDING) and COMPLETION
--   (refused after expiry/cancel). An already-issued token can still write
--   its one object path until its exp; that object is never attached.
--
-- ORDER / COMPATIBILITY
--   Apply with or after 078 (078's INSERT rule accepts org/<org>/temp/<id>
--   for an own live session; 071's permission-only rule also accepts it, so
--   079 without 078 works too). Any client build works with 079.
--
-- ROLLBACK
--   Re-run 070's create_product_image_upload_session block, 019's
--   attach_product_image_upload_session_token block and 075's file. Sessions
--   created meanwhile keep their org/... path and still complete (the path
--   comparison is against the stored storage_path).
-- FORWARD RECOVERY
--   Idempotent (CREATE OR REPLACE + REVOKE/GRANT). Re-run the file.
--
-- VERIFICATION
--   SELECT proname, prosrc LIKE '%079%' FROM pg_proc WHERE proname IN
--     ('create_product_image_upload_session','attach_product_image_upload_session_token',
--      'complete_product_image_upload_session');                         -- 3 x t
--   SELECT has_function_privilege('anon',
--     'public.complete_product_image_upload_session(text,text,text,integer,text)', 'EXECUTE');  -- t
--   -- live: desktop "Upload from phone" -> new session's storagePath starts
--   -- with org/<org id>/temp/; phone upload completes; desktop shows the image.
--   -- harness: bash supabase/tests/phase-d/run.sh   (t14_upload_security)
--
-- NOT applied anywhere by this change. Generated by gen079.py (session
-- scratchpad; inputs: production snapshot, 070, 075).
-- ============================================================

-- 1/3 create_product_image_upload_session (070 body + 1 hunk)
CREATE OR REPLACE FUNCTION "public"."create_product_image_upload_session"("p_shop_id" "text" DEFAULT NULL::"text", "p_product_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user users;
  v_session_id text := 'pimg-' || replace(gen_random_uuid()::text, '-', '');
  v_token text := replace(gen_random_uuid()::text, '-', '')
                  || replace(gen_random_uuid()::text, '-', '')
                  || replace(gen_random_uuid()::text, '-', '')
                  || replace(gen_random_uuid()::text, '-', '');
  v_storage_path text := 'temp/' || v_session_id;
  v_product_id text;
  v_expires_at timestamptz := now() + interval '10 minutes';
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_user := current_app_user();
  IF v_user.id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- 079: organization-scoped object path (078 storage policies:
  -- org/<org>/temp/<session>). Minted here, never by the client.
  v_storage_path := 'org/' || v_user.org_id || '/temp/' || v_session_id;

  -- Phase G (070): organization isolation guard. Every shop / entity this
  -- call targets must belong to the caller's organization; a row of another
  -- organization is reported as not found (068 app_require_org). Placed
  -- before the idempotency gate so a rejected call leaves no key row.
  PERFORM public.app_require_org('shop', p_shop_id);
  PERFORM public.app_require_org('product', p_product_id);

  IF NOT (app_has_perm('product:create') OR app_has_perm('product:update')) THEN
    RAISE EXCEPTION 'You are not permitted to upload product images';
  END IF;

  IF p_shop_id IS NOT NULL
     AND app_role() <> 'ADMIN'
     AND app_shop_id() IS DISTINCT FROM p_shop_id THEN
    RAISE EXCEPTION 'You are not permitted to create an upload session for this shop';
  END IF;

  IF p_product_id IS NOT NULL AND EXISTS (SELECT 1 FROM products WHERE id = p_product_id) THEN
    v_product_id := p_product_id;
  END IF;

  INSERT INTO product_image_upload_sessions (
    id, token_hash, created_by, shop_id, product_id, storage_path, expires_at
  )
  VALUES (
    v_session_id, product_image_upload_token_hash(v_token), v_user.id,
    p_shop_id, v_product_id, v_storage_path, v_expires_at
  );

  RETURN jsonb_build_object(
    'sessionId', v_session_id,
    'token', v_token,
    'storagePath', v_storage_path,
    'expiresAt', v_expires_at,
    'status', 'PENDING'
  );
END;
$$;

-- 2/3 attach_product_image_upload_session_token (snapshot body + 1 hunk)
CREATE OR REPLACE FUNCTION "public"."attach_product_image_upload_session_token"("p_session_id" "text", "p_signed_upload_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user users;
  v_session product_image_upload_sessions;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_user := current_app_user();
  IF v_user.id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF COALESCE(btrim(p_signed_upload_token), '') = '' THEN
    RAISE EXCEPTION 'Signed upload token is required';
  END IF;

  SELECT * INTO v_session
    FROM product_image_upload_sessions
   WHERE id = p_session_id
     AND created_by = v_user.id
   FOR UPDATE;

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'Upload session not found';
  END IF;

  IF v_session.status <> 'PENDING' OR v_session.expires_at <= now() THEN
    -- 079 (same fix as 075): no UPDATE here - the RAISE rolls back the whole
    -- call, so the EXPIRED stamp / token clearing could never persist.
    -- Expiry is derived from expires_at by every reader; the non-raising
    -- readers (get_product_image_upload_session_status/_by_token) persist it.
    RAISE EXCEPTION 'Upload link is no longer active';
  END IF;

  UPDATE product_image_upload_sessions
     SET signed_upload_token = p_signed_upload_token
   WHERE id = v_session.id
   RETURNING * INTO v_session;

  RETURN jsonb_build_object(
    'sessionId', v_session.id,
    'storagePath', v_session.storage_path,
    'expiresAt', v_session.expires_at,
    'status', v_session.status
  );
END;
$$;

-- 3/3 complete_product_image_upload_session (075 body + 1 hunk)
CREATE OR REPLACE FUNCTION "public"."complete_product_image_upload_session"("p_token" "text", "p_storage_path" "text", "p_public_url" "text", "p_bytes" integer, "p_mime_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_session product_image_upload_sessions;
BEGIN
  IF COALESCE(length(p_token), 0) < 32 THEN
    RAISE EXCEPTION 'Invalid upload link';
  END IF;

  SELECT * INTO v_session
    FROM product_image_upload_sessions
   WHERE token_hash = product_image_upload_token_hash(p_token)
   FOR UPDATE;

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'Invalid upload link';
  END IF;

  IF v_session.status <> 'PENDING' THEN
    RAISE EXCEPTION 'Upload link is no longer active';
  END IF;

  IF v_session.expires_at <= now() THEN
    -- 075: reject with the same message as every other inactive session.
    -- No UPDATE here: the RAISE rolls back the whole call, so a status
    -- write could never persist (the 019 body's EXPIRED stamp was lost).
    -- Expiry is derived from expires_at by every reader, and the stamping
    -- readers (get_product_image_upload_session_status/_by_token) persist it.
    RAISE EXCEPTION 'Upload link is no longer active';
  END IF;

  IF p_storage_path IS DISTINCT FROM v_session.storage_path THEN
    RAISE EXCEPTION 'Upload path does not match this session';
  END IF;

  IF p_bytes IS NULL OR p_bytes <= 0 OR p_bytes > 102400 THEN
    RAISE EXCEPTION 'Uploaded image must be 100 KB or smaller';
  END IF;

  IF p_mime_type NOT IN ('image/webp', 'image/jpeg') THEN
    RAISE EXCEPTION 'Unsupported uploaded image type';
  END IF;

  IF COALESCE(btrim(p_public_url), '') = '' OR lower(p_public_url) LIKE 'data:%' THEN
    RAISE EXCEPTION 'Uploaded image URL must be a Storage URL';
  END IF;

  IF position('/storage/v1/object/public/product-images/' in p_public_url) = 0 THEN
    RAISE EXCEPTION 'Uploaded image URL must point to the product-images bucket';
  END IF;

  -- 079: the URL handed to the desktop must be THIS session's object (a
  -- token holder could otherwise substitute any URL containing the bucket
  -- path, e.g. on another host). getPublicUrl(storagePath) always ends so.
  IF right(p_public_url, length('/storage/v1/object/public/product-images/' || v_session.storage_path))
     IS DISTINCT FROM '/storage/v1/object/public/product-images/' || v_session.storage_path THEN
    RAISE EXCEPTION 'Uploaded image URL does not match this upload session';
  END IF;

  UPDATE product_image_upload_sessions
     SET status = 'COMPLETED',
         storage_path = p_storage_path,
         public_url = p_public_url,
         bytes = p_bytes,
         mime_type = p_mime_type,
         signed_upload_token = NULL,
         completed_at = now()
   WHERE id = v_session.id
   RETURNING * INTO v_session;

  RETURN jsonb_build_object(
    'sessionId', v_session.id,
    'storagePath', v_session.storage_path,
    'publicUrl', v_session.public_url,
    'bytes', v_session.bytes,
    'mimeType', v_session.mime_type,
    'expiresAt', v_session.expires_at,
    'status', v_session.status
  );
END;
$$;

REVOKE ALL ON FUNCTION "public"."create_product_image_upload_session"(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION "public"."create_product_image_upload_session"(text, text) TO authenticated, service_role;
REVOKE ALL ON FUNCTION "public"."attach_product_image_upload_session_token"(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION "public"."attach_product_image_upload_session_token"(text, text) TO authenticated, service_role;
REVOKE ALL ON FUNCTION "public"."complete_product_image_upload_session"(text, text, text, integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."complete_product_image_upload_session"(text, text, text, integer, text) TO anon, authenticated, service_role;

NOTIFY pgrst, 'reload schema';
